for (int x : v) { ... } 等价于:
  auto __begin = v.begin(), __end = v.end();
  for (; __begin != __end; ++__begin) { int x = *__begin; ... }

实测遍历结果: 1 2 3

关键点：__end 在循环开始时就固定了 ——
循环体内增删元素会让迭代器失效，而 __end 不会跟着更新

code:
#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> v{1, 2, 3};

    cout << "for (int x : v) { ... } 等价于:\n";
    cout << "  auto __begin = v.begin(), __end = v.end();\n";
    cout << "  for (; __begin != __end; ++__begin) { int x = *__begin; ... }\n\n";
    cout << "实测遍历结果:";
    for (auto __begin = v.begin(), __end = v.end(); __begin != __end; ++__begin) {
        int x = *__begin;
        cout << " " << x;
    }
    cout << "\n\n";
    cout << "关键点：__end 在循环开始时就固定了 ——\n";
    cout << "循环体内增删元素会让迭代器失效，而 __end 不会跟着更新\n";
}
